// Parser Mercasa central portal — extrae precios de todos los mercas × productos
const cheerio = require('cheerio')
const html = $input.first().json.data
const $ = cheerio.load(html)

// Fecha del scraping = hoy (Mercasa muestra la semana actual por defecto)
const hoy = new Date().toISOString().split('T')[0]

// Slugs de mercas en el orden que aparecen en las columnas
const MERCAS = ['mercamadrid', 'mercabarna', 'mercabilbao', 'mercavalencia', 'mercasevilla']

// Categorías esperadas (rows de cabecera)
const CATEGORIAS = ['Frutas', 'Hortalizas', 'Pescado Fresco', 'Pescado Congelado', 'Carnes']

const items = []
let currentCat = null

// La tabla principal es la primera de la página (la segunda es de cookies)
const table = $('table').first()

table.find('tr').each((_, tr) => {
  const cells = $(tr).find('td, th').map((_, c) => $(c).text().trim()).get()
  if (cells.length === 0) return

  // Filas de cabecera de categoría — 1 sola celda con el nombre
  if (cells.length === 1 && CATEGORIAS.includes(cells[0])) {
    currentCat = cells[0]
    return
  }

  // Filas de sub-cabecera (fechas) — se ignoran
  if (cells[0] === 'Productos' || /^\d{1,2}\/\d{1,2}$/.test(cells[0])) return

  // Filas de datos — 11 celdas: producto + 5 mercas × 2 fechas
  if (cells.length !== 11) return

  const producto = cells[0]
  if (!producto || producto.length < 2) return

  MERCAS.forEach((merca, mi) => {
    // Cogemos el precio de la segunda fecha (la más reciente)
    const rawPrice = cells[1 + mi * 2 + 1]
    if (!rawPrice || rawPrice === '' || rawPrice === '-') return
    const precio = parseFloat(rawPrice.replace(',', '.'))
    if (!Number.isFinite(precio) || precio <= 0) return

    items.push({
      json: {
        producto_scraper: producto,
        categoria: currentCat,
        mercado_slug: merca,
        precio_kg: precio,
        fecha: hoy
      }
    })
  })
})

if (items.length === 0) {
  throw new Error('Parser no extrajo ningun precio — revisar HTML de Mercasa (puede haber cambiado estructura)')
}

return items

// Construye el registro de precio con IDs de mercado hardcodeados (poblados al crear la base)
const MERCADO_IDS = {
  mercabarna: 'recLy7kRK4US0OMAp',
  mercamadrid: 'recxOTy49LL6j7kgL',
  mercavalencia: 'recKPDMam37kiVYwA',
  mercabilbao: 'rec2q8E6OICBjFhzN',
  mercasevilla: 'recLr4elsMTrhQu2R'
}

const ing = $input.first().json                                     // ingrediente Airtable
const scraper = $('Code · parser Mercasa').item.json                // datos scraper

const mercadoId = MERCADO_IDS[scraper.mercado_slug]
if (!mercadoId) throw new Error('Mercado desconocido: ' + scraper.mercado_slug)

const idRegistro = `${ing.id}-${mercadoId}-${scraper.fecha}`

return [{
  json: {
    id_registro: idRegistro,
    fecha: scraper.fecha,
    precio_kg: scraper.precio_kg,
    unidad: 'kg',
    procedencia_scraper: 'n8n_mercasa_central',
    ingrediente: [ing.id],
    mercado: [mercadoId]
  }
}]
